/**
 * TS port of ei's SanitizeName (export/imports.go) + splitCamelCase
 * (export/hcl_organize.go). Used ONLY for brand-new hand-authored entities
 * (plan §4.2) — exported entities keep their RECORDED tfLabel, because
 * SanitizeName is lossy and the exact exported label can't be re-derived.
 * Ported faithfully so a generated label for a new entity matches what ei
 * would generate on its next export of that entity.
 */
/**
 * Insert spaces at CamelCase word boundaries. "ValidateAdGroupRequest" →
 * "Validate Ad Group Request"; acronyms stay together ("WaaSRequest" →
 * "WaaS Request", "DLUpdate" → "DL Update", "A2ATranscript" → "A2A Transcript").
 */
export function splitCamelCase(name) {
    const runes = [...name];
    const isUpper = (r) => r >= "A" && r <= "Z";
    const isLower = (r) => r >= "a" && r <= "z";
    const upperRunLen = (i) => {
        let n = 0;
        for (let j = i; j < runes.length && isUpper(runes[j]); j++)
            n++;
        return n;
    };
    let out = "";
    for (let i = 0; i < runes.length; i++) {
        const r = runes[i];
        if (i > 0 && isUpper(r)) {
            const prev = runes[i - 1];
            const next = runes[i + 1];
            if ((isLower(prev) && (next === undefined || isLower(next))) ||
                (isUpper(prev) && next !== undefined && isLower(next)) ||
                (isLower(prev) && next !== undefined && isUpper(next) && upperRunLen(i) >= 3)) {
                out += " ";
            }
        }
        out += r;
    }
    return out;
}
/**
 * tfLabel ↔ tsLabel: the ONE naming convention EDK owns.
 *
 * A display name is converted to a tfLabel exactly once, by ei's frozen
 * SanitizeName, at export time — lossy, and not ours to define. Everything
 * EDK-side derives from the tfLabel through this LOSSLESS bijection:
 *
 *   tfLabel (snake_case, terraform address)  ↔  tsLabel (camelCase, catalog key)
 *   seans_snowflake_cloud_link               ↔  seansSnowflakeCloudLink
 *   claude_sonnet_4_5                        ↔  claudeSonnet_4_5
 *   gpt_4_1                                  ↔  gpt_4_1
 *
 * Digits can't carry case, so an underscore BEFORE A DIGIT survives into the
 * tsLabel — that's what keeps `ops_1` and `ops1` distinct in both directions.
 * Hand-authored entities work backwards: the author writes the tsLabel (bag
 * key / file name) and `elementum build` derives the tfLabel via the inverse.
 */
/** The alphabet ei's SanitizeName emits — the bijection's valid domain. */
const TF_LABEL_RE = /^[a-z_][a-z0-9_]*$/;
export function tfLabelToTsLabel(tfLabel) {
    if (!TF_LABEL_RE.test(tfLabel)) {
        // Outside [a-z0-9_] the conversion is not a bijection (an uppercase
        // letter survives forward but decodes differently backward, silently
        // colliding with a legitimate label). Loud, per the contract-drift rule.
        throw new Error(`tfLabel "${tfLabel}" is outside ei's SanitizeName alphabet ([a-z0-9_], non-digit start) — refusing a lossy conversion`);
    }
    let out = "";
    let i = 0;
    while (i < tfLabel.length) {
        const c = tfLabel[i];
        if (c === "_" && i + 1 < tfLabel.length && /[a-z]/.test(tfLabel[i + 1])) {
            out += tfLabel[i + 1].toUpperCase();
            i += 2;
            continue;
        }
        out += c;
        i++;
    }
    return out;
}
export function tsLabelToTfLabel(tsLabel) {
    let out = "";
    for (const c of tsLabel) {
        out += /[A-Z]/.test(c) ? "_" + c.toLowerCase() : c;
    }
    return out;
}
/**
 * A tsLabel is canonical when it survives the round trip — i.e. it is the
 * exact image of its own tfLabel. Build validates authored keys with this
 * (loud error otherwise) so every authored identifier has a well-defined
 * terraform address.
 */
export function isCanonicalTsLabel(tsLabel) {
    if (!/^[A-Za-z0-9_]+$/.test(tsLabel))
        return false;
    const tf = tsLabelToTfLabel(tsLabel);
    return TF_LABEL_RE.test(tf) && tfLabelToTsLabel(tf) === tsLabel;
}
/**
 * Lowercase snake slug for display names: "To Do" → "to_do". Used where a
 * label derives from a NAME rather than an authored key — stage keys (ei's
 * stage-key shape) and the field bag-key fallback when `__refName` is absent.
 */
export function snakeSlug(s) {
    return s
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, "_")
        .replace(/^_+|_+$/g, "");
}
/** Faithful port of ei's SanitizeName: platform name → HCL identifier. */
export function sanitizeName(name) {
    let s = splitCamelCase(name).toLowerCase();
    for (const sep of [" ", "-", ".", ":", "/", "\\"]) {
        s = s.replaceAll(sep, "_");
    }
    s = [...s].filter((r) => (r >= "a" && r <= "z") || (r >= "0" && r <= "9") || r === "_").join("");
    while (s.includes("__")) {
        s = s.replaceAll("__", "_");
    }
    s = s.replace(/^_+|_+$/g, "");
    if (s.length > 0 && s[0] >= "0" && s[0] <= "9") {
        s = "_" + s;
    }
    return s === "" ? "resource" : s;
}
/** Matches a raw platform id (v4-shaped, case-insensitive) — used to recognize an orphaned reference that round-trips as a bare id rather than a resolved name/label. */
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
/** True when `value` has the shape of a platform id (not a validity check — just the wire shape). */
export function isUuid(value) {
    return UUID_RE.test(value);
}
/**
 * Prefix for app-owned child resource labels in a shared `.tf/out/` workspace.
 * Uses the platform namespace (`appTfLabel`), matching ei's `AppResourceName`.
 */
export function appResourceLabelPrefix(appTfLabel) {
    return `apps_${appTfLabel}_`;
}
/** Prefix for element-owned children in a shared `.tf/out/` workspace. */
export function elementResourceLabelPrefix(elementTfLabel) {
    return `elements_${elementTfLabel}_`;
}
/**
 * App-owned child resource label: `apps_<namespace>_<namespace>_<childPart>`, ALWAYS.
 * The owner prefix is prepended unconditionally — never collapsed just because `childPart`
 * already happens to start with `<ns>_` (issue #115: a field named e.g. `sourcingStatus` under
 * app `sourcing` is a real, distinct field from one named `status`, not a re-encoding of it) —
 * to keep the encoding injective. `childPartFromScopedLabel` is its exact inverse (strips
 * `apps_<ns>_` then one more `<ns>_`, unconditionally).
 */
export function appScopedResourceLabel(appTfLabel, childPart) {
    return `${appResourceLabelPrefix(appTfLabel)}${appTfLabel}_${childPart}`;
}
/**
 * Element-owned child resource label: `elements_<namespace>_<namespace>_<childPart>`, ALWAYS —
 * same unconditional doubling as {@link appScopedResourceLabel}, for the same reason (issue
 * #115): a field named e.g. `ticketsPriority` under element `tickets` is a real, distinct field
 * from one named `priority`, not a re-encoding of it. A prior version of this function skipped
 * the double when `childPart` already started with `<ns>_`, which collapsed both onto the same
 * label — reported live against a real `tickets` element field pulling ambiguously.
 *
 * One-time upgrade characteristic, not an ongoing bug: this changes the computed address ONLY
 * for a STALE bag key an older (pre-fix) pull already wrote to disk and that was never
 * re-pulled — the old extractor never stripped the namespace, so it left prefixed bag keys
 * (e.g. `ticketsActive`) that now over-double when rebuilt. A field FRESHLY re-extracted with
 * `childPartFromScopedLabel`'s current (also-fixed) stripping round-trips to the exact same
 * address ei already uses — see `__tests__/tf/labels.test.ts`'s "element-prefixed child labels
 * round-trip" block. Re-pull an existing element (`elementum pull element <ns>`) before your
 * next build/plan if it predates this fix; adoption's rename guard (board item 225,
 * `docs/design/rename-label-identity.md`) safely `state mv`s any address that does shift.
 */
export function elementScopedResourceLabel(elementTfLabel, childPart) {
    return `${elementResourceLabelPrefix(elementTfLabel)}${elementTfLabel}_${childPart}`;
}
/** Emit a scoped child label for the owning stream root kind. */
export function scopedResourceLabel(ownerTfLabel, childPart, scope) {
    return scope === "app" ? appScopedResourceLabel(ownerTfLabel, childPart) : elementScopedResourceLabel(ownerTfLabel, childPart);
}
/** Strip a scoped child label back to its bare form (no-op when unprefixed). */
export function bareChildResourceLabel(ownerTfLabel, scopedLabel, scope = "app") {
    const prefix = scope === "app" ? appResourceLabelPrefix(ownerTfLabel) : elementResourceLabelPrefix(ownerTfLabel);
    return scopedLabel.startsWith(prefix) ? scopedLabel.slice(prefix.length) : scopedLabel;
}
/**
 * Child part after the owner namespace — bag keys omit the namespace prefix
 * for both apps and elements. Strips `apps_<ns>_`/`elements_<ns>_` then
 * exactly one `<ns>_` — the exact inverse of `appScopedResourceLabel`'s /
 * `elementScopedResourceLabel`'s always-double encoding (issue #115). The
 * `startsWith` check is therefore always true for a well-formed label; it is
 * kept only to no-op on unprefixed input.
 */
export function childPartFromScopedLabel(ownerTfLabel, scopedLabel, scope) {
    const bare = bareChildResourceLabel(ownerTfLabel, scopedLabel, scope);
    const nsPrefix = `${ownerTfLabel}_`;
    return bare.startsWith(nsPrefix) ? bare.slice(nsPrefix.length) : bare;
}
/** Scoped terraform label → authoring bag key / ref key. */
export function scopedLabelToBagKey(ownerTfLabel, scopedLabel, scope = "app") {
    return tfLabelToTsLabel(childPartFromScopedLabel(ownerTfLabel, scopedLabel, scope));
}
